<?php require_once 'config/config.php'; $pageTitle='Contact';$sent=false;$error='';$subject=$_GET['subject']??''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$message=trim($_POST['message']??'');$type=trim($_POST['inquiry_type']??'general');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$message)$error='Please provide your name, a valid email, and a message.';else{$st=db()->prepare("INSERT INTO inquiries (name,email,phone,message,inquiry_type) VALUES (?,?,?,?,?)");$st->execute([$name,$email,$phone,$message,$type]);$sent=true;}}require 'includes/header.php'; ?>
